// Custom cell models generated by NESTML from models/nestml/*.nestml (scripts/build-nestml.sh) and compiled
// statically into libspike. NEST has no dynamic loading here (ltdl off), so the models are registered by hand.
#pragma once
#include <string>
#include <vector>

namespace spike
{
// Register every NESTML model with the NEST kernel. Idempotent per kernel state; call after each ResetKernel
// and after every change of the thread count (both drop all registered models). No-op if the models were not generated.
void register_nestml_models();
// Names of the compiled-in NESTML models (empty if scripts/build-nestml.sh was not run before configuring).
const std::vector< std::string >& nestml_model_names();
} // namespace spike
